do $$
begin
create temp table _ib(branch text,pg int,g11a text,g11ah int,g11b text,g11bh int,g11c text,g11ch int,g12a text,g12ah int,g12b text,g12bh int,g12c text,g12ch int) on commit drop;
insert into _ib values
('Çatı Sistemleri',14,'Ahşap Çatılar',2,'Çatı Sistemleri Meslek Resmi',3,'Yapı Maliyet Hesapları',2,'Bina ve Yerleşim Rölövesi',2,'Çatı Yalıtımı ve Kaplama',2,'Bilgisayarla Çizim',3),('Çelik Yapı Teknik Ressamlığı',15,'Çelik Yapı Proje Çizimleri',2,'Bilgisayarla Çelik Yapı Proje Çizimleri',3,'Yapı Maliyet Hesapları',2,'Yapı Statik Hesapları',2,'Çelik Yapı İmalatları',2,'Bilgisayarla Üç Boyutlu Modelleme',3),('İç Mekân Teknik Ressamlığı',16,'İç Mekân Çizimleri',2,'Bilgisayarla İç Mekân Çizimleri',3,'Yapı Maliyet Hesapları',2,'Bina ve Yerleşim Rölövesi',2,'Renklerle Tasarım',2,'Bina Maketleri',3),('Mimari Restorasyon',17,'Ahşap Kâgir Restorasyonu',2,'Rölöve Restorasyon Proje Çizimleri',3,'Yapı Maliyet Hesapları',2,'Bezeme Restorasyonu',3,'Süsleme Sanatı',1,'Bilgisayarla Rölöve Restorasyon Proje Çizimleri',3),('Mimari Yapı Teknik Ressamlığı',18,'Mimari Proje Çizimleri',2,'Bilgisayarla Mimari Proje Çizimleri',3,'Yapı Maliyet Hesapları',2,'Yapı Statik Hesapları',2,'Bina ve Yerleşim Rölövesi',2,'Bina Maketleri',3),('Statik Yapı Teknik Ressamlığı',19,'Statik Proje Çizimleri',2,'Bilgisayarla Statik Proje Çizimleri',3,'Yapı Maliyet Hesapları',2,'Yapı Statik Hesapları',2,'Bina ve Yerleşim Rölövesi',2,'Bina Maketleri',3),('Yapı Dekorasyonu',20,'İç Mekân Dekorasyon ve Kartonpiyer',3,'Yapıda Boyalar',2,'Yapı Maliyet Hesapları',2,'İç Mekân Dekorasyon Meslek Resmi',2,'Renklerle Tasarım',2,'Bilgisayarla Çizim',3),('Yapı Duvar ve Sıva Sistemleri',21,'Yapıda Duvarlar',2,'Yapı Duvar ve Sıva Meslek Resmi',3,'Yapı Maliyet Hesapları',2,'Yapıda Sıvalar',2,'Bina ve Yerleşim Rölövesi',2,'Bilgisayarla Çizim',3),('Yapı Yalıtımı',22,'Yapıda Yalıtım',2,'Yalıtım Meslek Resmi',3,'Yapı Maliyet Hesapları',2,'Yapıda Boyalar',2,'Bina ve Yerleşim Rölövesi',2,'Bilgisayarla Çizim',3),('Yapı Yüzey Kaplama',23,'Duvar ve Zemin Kaplamaları',2,'Parke Taşı ve Bordür Kaplama',3,'Yapı Maliyet Hesapları',2,'Yüzey Kaplama Meslek Resmi',2,'Bina ve Yerleşim Rölövesi',2,'Bilgisayarla Çizim',3);
insert into course_catalog(id,name,category,active) select gen_random_uuid(),x.n,'uygulama',true from (select g11a n from _ib union select g11b from _ib union select g11c from _ib union select g12a from _ib union select g12b from _ib union select g12c from _ib)x where not exists(select 1 from course_catalog c where c.name=x.n);
insert into official_curriculum_profiles(id,effective_academic_year,school_type,school_subtype,program_type,field_name,branch_name,grade_level,required_course_count,required_hour_total,elective_course_min,elective_course_max,elective_hour_min,elective_hour_max,total_hour_min,total_hour_max,total_hour_target,group_rules,source_file_name,source_decision_no,source_note,active,schedule_variant,common_hours,vocational_hours,elective_vocational_hours,elective_hours,guidance_hours,enterprise_hours,applicability_status,source_page,parsed_constraints,academic_support_hours)
select gen_random_uuid(),p.effective_academic_year,p.school_type,p.school_subtype,p.program_type,p.field_name,i.branch,p.grade_level,p.required_course_count,p.required_hour_total,p.elective_course_min,p.elective_course_max,p.elective_hour_min,p.elective_hour_max,p.total_hour_min,p.total_hour_max,p.total_hour_target,p.group_rules,'https://meslek.meb.gov.tr/upload/cop12_mem/2021_insaat_mem_cop.pdf','2021-33','Parantezli temel ders saatleri diploma programı için ilave fark dersleridir; ustalık ve diploma profilleri ayrı tutulur.',true,p.schedule_variant,p.common_hours,p.vocational_hours,p.elective_vocational_hours,p.elective_hours,p.guidance_hours,p.enterprise_hours,'CURRENTLY_VALID',i.pg,p.parsed_constraints,p.academic_support_hours from official_curriculum_profiles p cross join _ib i where p.school_type='MESEM' and p.field_name='İnşaat Teknolojisi' and p.branch_name='Ahşap Yapı Sistemleri' and not exists(select 1 from official_curriculum_profiles q where q.school_type='MESEM' and q.field_name='İnşaat Teknolojisi' and q.branch_name=i.branch and q.grade_level=p.grade_level and q.schedule_variant=p.schedule_variant and q.active);
insert into official_course_schedule_catalog(id,effective_academic_year,school_type,program_type,grade_level,course_id,category,hour_options,max_selections,repeat_across_years,elective_group_key,source_file_name,source_note,active,field_name,branch_name,parsed_constraints,school_subtype,source_decision_no,source_decision_date,source_page,source_section,parser_confidence,needs_review,schedule_variant)
select gen_random_uuid(),s.effective_academic_year,s.school_type,s.program_type,s.grade_level,s.course_id,s.category,s.hour_options,s.max_selections,s.repeat_across_years,s.elective_group_key,'https://meslek.meb.gov.tr/upload/cop12_mem/2021_insaat_mem_cop.pdf',s.source_note,true,s.field_name,i.branch,s.parsed_constraints,s.school_subtype,'2021-33',s.source_decision_date,i.pg,s.source_section,s.parser_confidence,false,s.schedule_variant from official_course_schedule_catalog s cross join _ib i where s.school_type='MESEM' and s.field_name='İnşaat Teknolojisi' and s.branch_name='Ahşap Yapı Sistemleri' and s.grade_level in (9,10) and not exists(select 1 from official_course_schedule_catalog q where q.school_type='MESEM' and q.field_name='İnşaat Teknolojisi' and q.branch_name=i.branch and q.grade_level=s.grade_level and q.schedule_variant=s.schedule_variant and q.course_id=s.course_id and q.active);
insert into official_course_schedule_catalog(id,effective_academic_year,school_type,program_type,grade_level,course_id,category,hour_options,max_selections,repeat_across_years,elective_group_key,source_file_name,source_note,active,field_name,branch_name,parsed_constraints,school_subtype,source_decision_no,source_decision_date,source_page,source_section,parser_confidence,needs_review,schedule_variant)
select gen_random_uuid(),'2026-2027','MESEM','MESEM',v.gr,c.id,case when v.n in ('Türk Dili ve Edebiyatı','Din Kültürü ve Ahlak Bilgisi','Matematik') then 'zorunlu' else 'uygulama' end,array[v.h]::smallint[],1,false,null,'https://meslek.meb.gov.tr/upload/cop12_mem/2021_insaat_mem_cop.pdf','2021-33 resmi haftalık ders çizelgesi',true,'İnşaat Teknolojisi',i.branch,'{}'::jsonb,null,'2021-33',null,i.pg,'HAFTALIK DERS ÇİZELGESİ',1,false,v.var from _ib i cross join lateral (values (11,'USTALIK','Din Kültürü ve Ahlak Bilgisi',2),(11,'USTALIK','Matematik',1),(11,'USTALIK','İşletmelerde Mesleki Eğitim',32),(11,'USTALIK',i.g11a,i.g11ah),(11,'USTALIK',i.g11b,i.g11bh),(11,'USTALIK',i.g11c,i.g11ch),(11,'DIPLOMA','Din Kültürü ve Ahlak Bilgisi',2),(11,'DIPLOMA','Matematik',3),(11,'DIPLOMA','Türk Dili ve Edebiyatı',2),(11,'DIPLOMA','İşletmelerde Mesleki Eğitim',32),(11,'DIPLOMA',i.g11a,i.g11ah),(11,'DIPLOMA',i.g11b,i.g11bh),(11,'DIPLOMA',i.g11c,i.g11ch),(12,'USTALIK','Din Kültürü ve Ahlak Bilgisi',2),(12,'USTALIK','İşletmelerde Mesleki Eğitim',32),(12,'USTALIK','Ahilik Kültürü ve Girişimcilik',1),(12,'USTALIK',i.g12a,i.g12ah),(12,'USTALIK',i.g12b,i.g12bh),(12,'USTALIK',i.g12c,i.g12ch),(12,'DIPLOMA','Din Kültürü ve Ahlak Bilgisi',2),(12,'DIPLOMA','Matematik',3),(12,'DIPLOMA','Türk Dili ve Edebiyatı',3),(12,'DIPLOMA','İşletmelerde Mesleki Eğitim',32),(12,'DIPLOMA','Ahilik Kültürü ve Girişimcilik',1),(12,'DIPLOMA',i.g12a,i.g12ah),(12,'DIPLOMA',i.g12b,i.g12bh),(12,'DIPLOMA',i.g12c,i.g12ch)) v(gr,var,n,h) join course_catalog c on c.name=v.n where not exists(select 1 from official_course_schedule_catalog q where q.school_type='MESEM' and q.field_name='İnşaat Teknolojisi' and q.branch_name=i.branch and q.grade_level=v.gr and q.schedule_variant=v.var and q.course_id=c.id and q.active);
end $$;